        'resources.guides.card1.title': 'The Ultimate ATS Algorithm Hack',
        'resources.guides.card1.body': 'Corporate Applicant Tracking Systems (ATS) score candidates based on keyword frequency, title alignment, and structural text readability. Learn how to design a high-fidelity plain layout that parses perfectly on Workday, Taleo, and Greenhouse ecosystems.',
        'resources.guides.card1.readTime': '5 min read',
        'resources.guides.card1.tag': 'ATS COMPLIANT',
        'resources.guides.card2.title': 'Writing Impactful STAR Bullet Points',
        'resources.guides.card2.body': 'Never write passive resume lines like "Assisted with tech projects." Use the **STAR formula**: Describe the **Situation**, state your **Task**, list your dynamic **Action**, and state the verifiable **Result**. Aim to quantify at least 50% of your listed achievements.',
        'resources.guides.card2.readTime': '4 min read',
        'resources.guides.card2.tag': 'STAR METHOD',
        'resources.guides.card3.title': 'Single vs. Two-Page CV Structures',
        'resources.guides.card3.body': 'Candidates with under 5 years of active career history must stick to a pristine single A4 sheet layout. Experienced professionals can scale up to 2 pages, provided the second page lists highly specialized tech credentials and leadership architectures.',
        'resources.guides.card3.readTime': '6 min read',
        'resources.guides.card3.tag': 'A4 PAGE-BREAKS',
        'resources.guides.banner.title': 'Why CVBase Vector Resumes Rank Higher',
        'resources.guides.banner.body': 'Standard document editors convert text lines into disorganized visual clusters or nested matrices which scanners read as garbled gibberish. CVBase maintains strict linear character codes. Every printed block features crisp, searchable vector properties, achieving flawless parse integrity across recursive indexing scrapers.',
        'resources.guides.banner.point1': 'No flat graphics',
        'resources.guides.banner.point2': 'Selectable character layers',
        'resources.guides.banner.point3': 'True-to-life standard layout margins',
        'resources.guides.banner.cardTitle': 'A4 Grid Mechanics',
        'resources.guides.banner.cardBody': 'Strict CSS print standards. Never clip headers or leave Orphan values at page bottoms.',
        'resources.verbs.title': 'Power Action Verbs Dictionary',
        'resources.verbs.subtitle': 'Inject high-impact verbs into your achievements to immediately command attention.',
        'resources.verbs.countFound': '{count} VERBS FOUND',
        'resources.verbs.searchPlaceholder': 'Search power verbs or definitions...',
        'resources.verbs.category.all': 'All',
        'resources.verbs.category.leadership': 'Leadership',
        'resources.verbs.category.creativity': 'Creativity',
        'resources.verbs.category.operations': 'Operations',
        'resources.verbs.category.research': 'Research',
        'resources.verbs.category.delivery': 'Delivery',
        'resources.verbs.copyTitle': 'Click to copy verb',
        'resources.verbs.noResults': 'No verbs match your current search constraints.',
        'resources.verbs.definition.spearheaded': 'Led a team, project, or movement to success from the beginning stages.',
        'resources.verbs.definition.orchestrated': 'Organized, managed, and executed complex multi-team initiatives.',
        'resources.verbs.definition.pioneered': 'Designed or developed some of the earliest processes, tools, or concepts.',
        'resources.verbs.definition.revamped': 'Redesigned or restructured an underperforming system to make it look or perform better.',
        'resources.verbs.definition.streamlined': 'Simplified and organized a complex, redundant workflow to save cost or time.',
        'resources.verbs.definition.formulated': 'Created a systematic strategy, policy, or framework using precise data analysis.',
        'resources.verbs.definition.scrutinized': 'Inspected raw systems or performance datasets closely for optimizations.',
        'resources.verbs.definition.deciphered': 'Translated abstract data, user signals, or analytics metrics into actionable strategies.',
        'resources.verbs.definition.surpassed': 'Exceeded established benchmarks, metrics, or revenue milestones.',
        'resources.verbs.definition.consolidated': 'Combined multiple resources or platforms to enhance efficiency.',
        'resources.verbs.example.spearheaded': 'Spearheaded the integration of cloud-native systems, accelerating pipeline velocity by 40%.',
        'resources.verbs.example.orchestrated': 'Orchestrated a cross-departmental transition to React-Vite, aligning 4 key product suites.',
        'resources.verbs.example.pioneered': 'Pioneered an AI-backed ATS parser auditing system used by 5,000 global candidates.',
        'resources.verbs.example.revamped': 'Revamped the customer onboarding portal, reducing signup friction by 33%.',
        'resources.verbs.example.streamlined': 'Streamlined container deployment parameters, cutting cloud compute costs by $12,000 annually.',
        'resources.verbs.example.formulated': 'Formulated an automated disaster recovery blueprint, ensuring 99.99% uptime.',
        'resources.verbs.example.scrutinized': 'Scrutinized database query executions, identifying bottleneck indices resulting in 2x speedups.',
        'resources.verbs.example.deciphered': 'Deciphered legacy database schema structures to enable a flawless cloud database migration.',
        'resources.verbs.example.surpassed': 'Surpassed previous delivery speed records by implementing automated unit test cycles.',
        'resources.verbs.example.consolidated': 'Consolidated 5 disparate tracking sheets into a unified real-time dashboard pipeline.',
        'resources.checklist.title': 'High-Fidelity Writing Checklist',
        'resources.checklist.subtitle': 'Step-by-step standards to secure and bulletproof candidate ranking.',
        'resources.checklist.resetTitle': 'Reset verification state',
        'resources.checklist.resetButton': 'Reset Checks',
        'resources.checklist.items.contact_clear': 'Contact details: Ensure your email, phone, location (city/state) and LinkedIn profiles are placed at the top and completely selectable (no graphics).',
        'resources.checklist.items.quantify_achieve': 'Quantification: At least 50% of your resume bullet points should contain an active metric (%, $, hours, size of team).',
        'resources.checklist.items.action_strong': 'Strong Verbs: Replace weak passive statements (like "responsible for" or "helped with") with punchy action verbs (e.g. "Spearheaded", "Streamlined").',
        'resources.checklist.items.standard_fonts': 'Standard Font Boundaries: Stick to universal fonts (Inter, Arial, Roboto, Helvetica, Georgia) styled with standard system margins.',
        'resources.checklist.items.no_nested_tables': 'ATS Readability: Avoid multi-nested tables, columns inside columns, or colored text overlays. Keep structures linear and parseable.',
        'resources.checklist.items.reverse_chrono': 'Chronological Integrity: Display your experiences with the most recent positions first, listing clear dates with month and year.',
        'resources.checklist.items.keyword_density': 'JD Keywords: Ensure primary technical nouns from the target job posting are included natively in your professional summaries or skills tags.',
        'resources.checklist.items.single_page_limit': 'Page Count Discipline: Keep early to mid-career resumes strictly to 1-2 pages, avoiding single-sentence trailing pages.',
