        'landing.whyCvBase.eyebrow': 'Por qué CVbase',
        'landing.whyCvBase.heading.prefix': 'Más allá de los robots. Frente a',
        'landing.whyCvBase.heading.highlight': 'los humanos',
        'landing.whyCvBase.intro': 'La mayoría de los CV son rechazados por el software antes de que un reclutador los lea. CVbase está diseñado para ambas audiencias: una estructura legible por máquinas por debajo y una tipografía cuidada por encima.',
        'landing.whyCvBase.reasons.atsFriendly.title': 'Compatible con ATS por diseño',
        'landing.whyCvBase.reasons.atsFriendly.description': 'Todas las plantillas son leídas sin errores por los sistemas de seguimiento de candidatos, así que tu CV llega a ojos humanos.',
        'landing.whyCvBase.reasons.guidedEditor.title': 'Un editor guiado, a prueba de principiantes',
        'landing.whyCvBase.reasons.guidedEditor.description': 'Estructura paso a paso, sin necesidad de experiencia en diseño o redacción.',
        'landing.whyCvBase.reasons.currentTemplates.title': 'Plantillas siempre actualizadas',
        'landing.whyCvBase.reasons.currentTemplates.description': 'Diseños contemporáneos que se actualizan con regularidad para responder a lo que esperan los reclutadores hoy.',
