        'tipsCard.skills.1': 'Incluez à la fois des « compétences techniques » (comme « Python », « Photoshop ») et des « compétences relationnelles » (comme « Leadership », « Communication »).',
        'tipsCard.skills.2': 'Ne listez pas de compétences que vous ne maîtrisez pas.',
        'tipsCard.skills.3': 'Vérifiez les compétences requises dans l\'offre d\'emploi et ajoutez-les si vous les possédez.',
