        'tipsCard.certifications.2': 'Indiquez le nom complet et officiel de la certification pour qu\'elle soit reconnue par les ATS.',
        'tipsCard.certifications.3': 'Si une certification a une date d\'expiration, veillez à l\'indiquer, surtout si elle est encore valide.',
        'tipsCard.languages.1': 'Listez les langues que vous maîtrisez à un niveau professionnel.',
        'tipsCard.languages.2': 'Utilisez des niveaux standards comme « Langue maternelle », « Courant » ou « Intermédiaire ».',
        'tipsCard.languages.3': 'N\'incluez que les langues pertinentes pour le poste ou que vous maîtrisez à un niveau élevé.',
        'tipsCard.awards.1': 'Mettez en avant les distinctions qui démontrent votre excellence dans votre domaine.',
        'tipsCard.awards.2': 'Incluez les prix d\'associations professionnelles, d\'anciens employeurs ou d\'institutions académiques.',
        'tipsCard.awards.3': 'Expliquez brièvement l\'importance du prix si elle n\'est pas évidente.',
        'tipsCard.trainings.1': 'Listez les ateliers, bootcamps ou séminaires qui ont renforcé vos compétences professionnelles.',
        'tipsCard.trainings.2': 'Concentrez-vous sur les formations pertinentes pour le poste visé.',
        'tipsCard.trainings.3': 'Indiquez l\'organisme et la date pour renforcer la crédibilité.',
        'tipsCard.publications.1': 'Listez les articles, livres ou travaux de recherche que vous avez rédigés ou co-rédigés.',
        'tipsCard.publications.2': 'Indiquez le titre, la date de publication et le nom de l\'éditeur ou de la revue.',
        'tipsCard.publications.3': 'Ajoutez un lien vers la publication si elle est disponible en ligne.',
        'tipsCard.volunteer.1': 'Mettez en avant les rôles de bénévolat démontrant du leadership ou des compétences pertinentes.',
        'tipsCard.volunteer.2': 'Indiquez le nom de l\'organisation, votre rôle et les dates de service.',
        'tipsCard.volunteer.3': 'Décrivez votre impact ou vos contributions clés, comme pour une expérience professionnelle.',
        'tipsCard.custom.1': 'Utilisez cette section pour tout ce qui ne trouve pas sa place ailleurs, comme les loisirs, centres d\'intérêt ou brevets.',
        'tipsCard.custom.2': 'Restez pertinent pour le poste ou montrez votre personnalité de façon professionnelle.',
