        'resources.tabs.checklist': 'Liste de contrôle interactive',
        'resources.tabs.ats': 'Bac à sable de conformité ATS',
        'resources.guides.card1.title': 'L\'astuce ultime de l\'algorithme ATS',
        'resources.guides.card1.body': 'Les systèmes de suivi des candidatures (ATS) des entreprises notent les candidats selon la fréquence des mots-clés, l\'alignement du titre et la lisibilité structurelle du texte. Apprenez à concevoir une mise en page simple et de haute fidélité qui s\'analyse parfaitement sur les écosystèmes Workday, Taleo et Greenhouse.',
        'resources.guides.card1.readTime': '5 min de lecture',
        'resources.guides.card1.tag': 'CONFORME ATS',
        'resources.guides.card2.title': 'Rédiger des puces STAR percutantes',
        'resources.guides.card2.body': 'N\'écrivez jamais de phrases passives comme « A participé à des projets techniques ». Utilisez la **formule STAR** : décrivez la **Situation**, indiquez votre **Tâche**, énumérez votre **Action** dynamique, puis exposez le **Résultat** vérifiable. Visez à quantifier au moins 50 % de vos réalisations listées.',
        'resources.guides.card2.readTime': '4 min de lecture',
        'resources.guides.card2.tag': 'MÉTHODE STAR',
        'resources.guides.card3.title': 'Structures de CV à une page ou deux pages',
        'resources.guides.card3.body': 'Les candidats ayant moins de 5 ans d\'expérience professionnelle active doivent s\'en tenir à une mise en page A4 impeccable sur une seule page. Les professionnels expérimentés peuvent passer à 2 pages, à condition que la seconde page présente des qualifications techniques très spécialisées et des structures de leadership.',
        'resources.guides.card3.readTime': '6 min de lecture',
        'resources.guides.card3.tag': 'SAUTS DE PAGE A4',
        'resources.guides.banner.title': 'Pourquoi les CV vectoriels CVBase sont mieux classés',
        'resources.guides.banner.body': 'Les éditeurs de documents standard transforment les lignes de texte en amas visuels désorganisés ou en matrices imbriquées que les scanners lisent comme du charabia. CVBase conserve des codes de caractères strictement linéaires. Chaque bloc imprimé présente des propriétés vectorielles nettes et recherchables, garantissant une intégrité d\'analyse parfaite face aux robots d\'indexation récursive.',
        'resources.guides.banner.point1': 'Pas de graphiques plats',
        'resources.guides.banner.point2': 'Calques de caractères sélectionnables',
        'resources.guides.banner.point3': 'Marges de mise en page standard fidèles à la réalité',
        'resources.guides.banner.cardTitle': 'Mécanique de grille A4',
        'resources.guides.banner.cardBody': 'Normes d\'impression CSS strictes. Ne coupez jamais les en-têtes et ne laissez jamais de lignes orphelines en bas de page.',
