        'resources.verbs.definition.spearheaded': 'A dirigé une équipe, un projet ou une initiative vers le succès dès les premières étapes.',
        'resources.verbs.definition.orchestrated': 'A organisé, géré et exécuté des initiatives complexes impliquant plusieurs équipes.',
        'resources.verbs.definition.pioneered': 'A conçu ou développé certains des tout premiers processus, outils ou concepts.',
        'resources.verbs.definition.revamped': 'A repensé ou restructuré un système peu performant pour en améliorer l\'apparence ou les performances.',
        'resources.verbs.definition.streamlined': 'A simplifié et organisé un flux de travail complexe et redondant pour réduire les coûts ou le temps.',
        'resources.verbs.definition.formulated': 'A créé une stratégie, une politique ou un cadre systématique à partir d\'une analyse de données précise.',
