        'resources.checklist.items.contact_clear': 'Coordonnées : assurez-vous que votre e-mail, téléphone, localisation (ville/région) et profil LinkedIn figurent en haut et sont entièrement sélectionnables (pas de graphiques).',
        'resources.checklist.items.quantify_achieve': 'Quantification : au moins 50 % des puces de votre CV doivent contenir une mesure active (%, $, heures, taille de l\'équipe).',
        'resources.checklist.items.action_strong': 'Verbes forts : remplacez les formulations passives faibles (comme « responsable de » ou « a aidé à ») par des verbes d\'action percutants (par ex. « A dirigé », « A optimisé »).',
        'resources.checklist.items.standard_fonts': 'Limites de police standard : privilégiez des polices universelles (Inter, Arial, Roboto, Helvetica, Georgia) avec des marges système standard.',
        'resources.checklist.items.no_nested_tables': 'Lisibilité ATS : évitez les tableaux multi-imbriqués, les colonnes dans les colonnes ou les superpositions de texte coloré. Gardez des structures linéaires et analysables.',
        'resources.checklist.items.reverse_chrono': 'Intégrité chronologique : présentez vos expériences en commençant par les postes les plus récents, avec des dates claires (mois et année).',
        'resources.checklist.items.keyword_density': 'Mots-clés de l\'offre : veillez à inclure naturellement les principaux termes techniques de l\'offre d\'emploi dans vos résumés professionnels ou vos étiquettes de compétences.',
        'resources.checklist.items.single_page_limit': 'Discipline sur le nombre de pages : limitez strictement les CV de début ou de milieu de carrière à 1-2 pages, en évitant les pages finales d\'une seule phrase.',
